function onMove(e) {
  if (!drag) return;
  const { item, list, offX, offY, sx, sy } = drag;

  // небольшой порог — чтобы не «подхватывать» случайное касание
  if (!drag.started && Math.hypot(e.clientX - sx, e.clientY - sy) <= 5) return;
  drag.started = true;

  const lr = list.getBoundingClientRect();
  item.style.left = (e.clientX - lr.left - offX) + 'px';
  item.style.top  = (e.clientY - lr.top - offY) + 'px';

  // find target: первый (в DOM) элемент, чей центр ниже указателя
  let target = null;
  for (const it of list.children) {
    if (it === item) continue;
    const r = it.getBoundingClientRect();
    if (e.clientY < r.top + r.height / 2) { target = it; break; }
  }

  // подсветка «прикрепления»
  qsa('.disc-item.is-over', list).forEach(el => el.classList.remove('is-over'));
  if (target) target.classList.add('is-over');

  if (target) {
    list.insertBefore(item, target);
  } else {
    if (list.lastElementChild !== item) list.appendChild(item);
  }
}

