function onMove(e) {
  if (!drag) return;
  const { item, list, offX, offY } = drag;
  const x = e.clientX - offX;
  const y = e.clientY - offY;
  item.style.left = x + 'px';
  item.style.top  = y + 'px';

  if (drag.threshold) {
    const started = Math.hypot(e.movementX || 0, e.movementY || 0) > 4;
    // просто помечаем — порог по фактическому сдвигу от начала
    drag.started = started || drag.wasDragging;
  }
  if (!drag.started) return;

  // find target: первый (в DOM) элемент, чей центр ниже указателя
  const all = Array.from(list.children);
  const pointerY = e.clientY;
  let target = null;
  for (let i = 0; i < all.length; i++) {
    const it = all[i];
    if (it === item) continue;
    const r = it.getBoundingClientRect();
    if (pointerY < r.top + r.height / 2) { target = it; break; }
  }

  // подсветка «прикрепления»
  const over = qsa('.disc-item.is-over', list);
  over.forEach(el => el.classList.remove('is-over'));
  if (target) target.classList.add('is-over');

  const currentIdx = all.indexOf(item);
  if (target) {
    if (list.children.indexOf(target) !== currentIdx) {
      list.insertBefore(item, target);
    }
  } else {
    if (list.lastElementChild !== item) list.appendChild(item);
  }
}

