/* ================= Result view (вместо apruve + редиректа) ================= */
function showResult() {
  const s = computeScore();
  resultShown = true;
  stepUI.style.display = 'none';
  resultEl.classList.add('is-visible');
  scoreEl.textContent = formatScore(s);

  // не даём «пробивать» табы во время показа результата
  tabs.forEach(t => t.disabled = true);
  qsa('[data-disc-prev], [data-disc-next], [data-disc-finish]').forEach(b => (b.disabled = true));
  // фокус на повторе
  requestAnimationFrame(() => retryBtn.focus({ preventScroll: true }));
}

function resetTest() {
  resultShown = false;
  // вернуть исходный порядок всех списков
  qsa('.disc-list', modal).forEach(list => {
    const orig = list._origOrder;
    if (!orig) return;
    Array.from(list.children).forEach(el => list.removeChild(el));
    orig.forEach(el => list.appendChild(el));
  });
