const WebSocket = require('ws');
const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');

const FILE_URL = 'file:///tmp/disc-pi-rauan7qv/run/index.html';
const PORT = 9999;
const OUT_DIR = '/tmp/ptest_out';
fs.mkdirSync(OUT_DIR, { recursive: true });

const sleep = ms => new Promise(r => setTimeout(r, ms));

function getJson() {
  return new Promise((resolve) => {
    http.get(`http://localhost:${PORT}/json`, (r) => {
      let d = '';
      r.on('data', c => d += c);
      r.on('end', () => { try { resolve(JSON.parse(d)); } catch (e) { resolve(null); } });
    }).on('error', () => resolve(null));
  });
}

const child = spawn(
  'google-chrome',
  [
    '--headless=new', '--no-sandbox', '--disable-gpu',
    '--disable-dev-shm-usage', '--hide-scrollbars',
    '--window-size=1440,900', `--remote-debugging-port=${PORT}`,
  ],
  { stdio: 'ignore' });

let ws, msgId = 0, pending = new Map();

function cdp(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++msgId;
    pending.set(id, { resolve, reject });
    setTimeout(() => { const p = pending.get(id); if (p) { pending.delete(id); reject(new Error(`timeout: ${method}`)); } }, 20000);
    ws.send(JSON.stringify({ id, method, params }));
  });
}

function evaluate(expr) {
  return cdp('Page.evaluate', { expression: expr, returnByValue: true })
    .then(r => r.result.value);
}

async function waitFor(cond, label) {
  for (let i = 0; i < 40; i++) {
    const ok = await cond();
    if (ok) return true;
    await sleep(300);
  }
  console.log(`WARN: ${label} timed out`);
  return false;
}

async function main() {
  console.log('Starting Chrome...');
  for (let i = 0; i < 60; i++) {
    const targets = await getJson();
    if (targets && targets.length) break;
    await sleep(400);
  }
  const targets = await getJson();
  const pageTarget = targets.find(t => t.type === 'page');
  if (!pageTarget) { console.error('No page target:', JSON.stringify(targets).slice(0,200)); process.exit(1); }

  const wsUrl = pageTarget.webSocketDebuggerUrl;
  ws = new WebSocket(wsUrl);
  ws.on('message', (m) => {
    const msg = JSON.parse(m);
    const p = pending.get(msg.id);
    if (p) { pending.delete(msg.id); p.resolve(msg); }
  });
  await new Promise((res) => { ws.on('open', res); });
  await cdp('Page.enable', {});
  await cdp('Page.navigate', { url: FILE_URL });
  await waitFor(async () => (await evaluate('document.readyState')) === 'complete', 'page load');

  const shot = (name) => new Promise((res) => {
    const id = ++msgId;
    pending.set(id, { resolve: (m) => { fs.writeFileSync(`${OUT_DIR}/${name}.png`, Buffer.from(m.result.data, 'base64')); res(m.result.data.length); }, reject: () => {} });
    ws.send(JSON.stringify({ id, method: 'Page.captureScreenshot' }));
  });
  await shot('01_home');
  console.log('home screenshot:', await shot('01_home_b'));

  // ---- Open modal ----
  const openOk = await evaluate(() => {
    const b = document.querySelector('[data-modal-open="wizardmodal"]');
    if (!b) return { open: false, btn: false };
    b.click();
    const m = document.querySelector('#wizardmodal');
    return { open: m && m.classList.contains('is-open') };
  });
  console.log('modal opened:', openOk.open);
  await sleep(300);
  await shot('02_modal_open');

  // ---- Verify step 1 state ----
  const s1 = await evaluate(() => {
    const t = document.querySelectorAll('.disc-tab');
    return {
      step: Array.from(t).find(x => x.classList.contains('is-active'))?.dataset.stepBtn,
      progress: document.querySelector('#discProgress').style.width,
      backDisabled: document.querySelector('[data-disc-prev]').disabled,
      nextHidden: document.querySelector('[data-disc-next]').hidden,
      finishHidden: document.querySelector('[data-disc-finish]').hidden,
    };
  });
  console.log('step1 state:', JSON.stringify(s1));

  // ---- Drag helper: move first item of list to bottom ----
  const dragFirstToBottom = async (listIndexInPanes) => {
    const result = await evaluate((n) => {
      const pane = document.querySelector('.disc-pane.is-active');
      if (!pane) return { err: 'no active pane' };
