async function main() {
  console.log('Starting Chrome...');
  await sleep(1500);
  const child = spawn('google-chrome', [
    '--headless=new', '--no-sandbox', '--disable-gpu',
    '--disable-dev-shm-usage', '--hide-scrollbars',
    '--window-size=1440,900', `--remote-debugging-port=${PORT}`,
  ], { stdio: ['ignore','ignore','pipe'] });

  let targets;
  for (let i = 0; i < 40 && !targets; i++) {
    targets = await getJson();
    await sleep(400);
  }
  console.log('targets found:', targets ? targets.length : 'NONE');
  const pageTarget = (targets || []).find(t => t.type === 'page');
  if (!pageTarget) { console.error('No page target'); child.kill(); process.exit(1); }

  ws = new WebSocket(pageTarget.webSocketDebuggerUrl);
  ws.on('open', () => {});
  ws.on('message', (m) => {
    const msg = JSON.parse(m);
    const p = pending.get(msg.id);
    if (p) { pending.delete(msg.id); p.resolve(msg); }
  });
  ws.on('error', (e) => console.error('ws error:', e));
  await new Promise(res => { ws.on('open', () => res()); });
  await cdp('Page.enable', {});
  await cdp('Page.navigate', { url: FILE_URL });
  const ready = await waitFor(async () => (await evaluate('document.readyState')) === 'complete', 'load');
  console.log('page loaded:', ready);
  if (!ready) { child.kill(); process.exit(1); }

  await shot('01_home');

  // ---- Open modal ----
  const openOk = await evaluate(() => {
    const b = document.querySelector('[data-modal-open="wizardmodal"]');
    if (!b) return { open: false };
    b.click();
    const m = document.querySelector('#wizardmodal');
    return { open: m && m.classList.contains('is-open') };
  });
  console.log('modal opened:', openOk.open);
  await sleep(300);
  await shot('02_modal_open');

  // ---- Verify step 1 state ----
  const s1 = await evaluate(() => {
    const t = Array.from(document.querySelectorAll('.disc-tab'));
    return {
      step: t.find(x => x.classList.contains('is-active'))?.dataset.stepBtn,
      progress: document.querySelector('#discProgress').style.width,
      backDisabled: document.querySelector('[data-disc-prev]').disabled,
      nextHidden: document.querySelector('[data-disc-next]').hidden,
      finishHidden: document.querySelector('[data-disc-finish]').hidden,
    };
  });
  console.log('step1 state:', JSON.stringify(s1));

  // ---- Drag helper: move first item of a given list index to bottom ----
  const dragFirstToBottom = (n) => evaluate((n) => {
    const pane = document.querySelector('.disc-pane.is-active');
    if (!pane) return { err: 'no active pane' };
    const lists = Array.from(pane.querySelectorAll('.disc-list'));
    const list = lists[n];
    if (!list) return { err: 'no list ' + n };
    const first = list.children[0];
    const r = first.getBoundingClientRect();
    const lr = list.getBoundingClientRect();
    const startX = lr.left + 40;
    const startY = r.top + r.height / 2;
    const endY = lr.bottom - 2;
    const steps = 8;
    const fire = (type, x, y) => {
      first.dispatchEvent(new PointerEvent(type, {
        bubbles: true, cancelable: true, view: window,
        pointerId: 1, pointerType: 'mouse', button: 0, isPrimary: true,
        clientX: x, clientY: y,
      }));
    };
    fire('pointerdown', startX, startY);
    for (let i = 1; i <= steps; i++) {
      fire('pointermove', startX, startY + (endY - startY) * (i / steps));
    }
    fire('pointerup', startX, endY);
    return Array.from(list.children).map(li => li.dataset.type);
  }, n);

  // ---- Walk through all 8 steps, dragging in each ----
  for (let step = 0; step < 8; step++) {
    for (let li = 0; li < 3; li++) {
      const r = await dragFirstToBottom(li);
      console.log(`  step${step + 1} list${li + 1} ->`, JSON.stringify(r));
    }
    if (step < 7) {
      await evaluate(() => document.querySelector('[data-disc-next]').click());
    } else {
      await evaluate(() => document.querySelector('[data-disc-finish]').click());
    }
    await sleep(200);
  }

  // ---- Check result ----
  const resState = await evaluate(() => {
    return {
      stepUIdisplay: document.querySelector('.disc-stepui').style.display,
      resultShown: document.querySelector('#discResult').classList.contains('is-visible'),
      resultDisplay: document.querySelector('#discResult').style.display,
      score: document.querySelector('#discScore')?.textContent,
    };
  });
  console.log('result state:', JSON.stringify(resState));
  const EXPECTED = 'D:2, I:-2, S:0, C:0';
  const PASS1 = resState.score === EXPECTED;
  console.log('SCORE PASS (expected "' + EXPECTED + '"):', PASS1 ? 'YES' : 'NO  got "' + resState.score + '"');
  await shot('03_result');

  // ---- Reset ----
  await evaluate(() => document.querySelector('#discRetry').click());
  await sleep(200);
  const resetState = await evaluate(() => {
    return {
      stepUIdisplay: document.querySelector('.disc-stepui').style.display,
      step: Array.from(document.querySelectorAll('.disc-tab')).find(x => x.classList.contains('is-active'))?.dataset.stepBtn,
      progress: document.querySelector('#discProgress').style.width,
    };
  });
  console.log('after reset:', JSON.stringify(resetState));
  const PASS2 = resetState.step === '0' && resetState.stepUIdisplay === '';
  console.log('RESET PASS (step 0, stepUI visible):', PASS2 ? 'YES' : 'NO');

  // ---- No-op drag check ----
  const noop = await evaluate(() => {
    const pane = document.querySelector('.disc-pane.is-active');
    const list = pane.querySelector('.disc-list');
    const first = list.children[0];
    const r = first.getBoundingClientRect();
    const startX = r.left + 40, startY = r.top + 20;
    const opts = { bubbles: true, clientX: startX, clientY: startY, pointerId: 1, pointerType: 'mouse', button: 0, isPrimary: true };
    first.dispatchEvent(new PointerEvent('pointerdown', { ...opts }));
    first.dispatchEvent(new PointerEvent('pointermove', { ...opts, clientX: startX + 2, clientY: startY + 2 }));
    first.dispatchEvent(new PointerEvent('pointerup', { ...opts, clientX: startX + 2, clientY: startY + 2 }));
    return Array.from(list.children).map(li => li.dataset.type);
  });
  const originalOrder = (await evaluate(() => {
    const pane = document.querySelector('.disc-pane.is-active');
    return Array.from(pane.querySelectorAll('.disc-list')).map(l => Array.from(l.children).map(li => li.dataset.type));
  }))[0];
  const PASS3 = JSON.stringify(noop) === JSON.stringify(originalOrder);
  console.log('NO-OP DRAG PASS (order unchanged):', PASS3 ? 'YES' : 'NO', 'order:', JSON.stringify(noop));

  // ---- Close modal ----
  await evaluate(() => {
    const m = document.querySelector('#wizardmodal');
    m.querySelector('[data-disc-close]').click();
  });
  const closeState = await evaluate(() => {
    return {
      modalOpen: document.querySelector('#wizardmodal').classList.contains('is-open'),
      bodyOverflow: document.body.style.overflow,
    };
  });
  console.log('after close:', JSON.stringify(closeState));
  const PASS4 = closeState.modalOpen === false && closeState.bodyOverflow === '';
  console.log('CLOSE PASS (modal closed, scroll unlocked):', PASS4 ? 'YES' : 'NO');
  await shot('04_closed');

  const all = PASS1 && PASS2 && PASS3 && PASS4;
  console.log('\n===== SUMMARY =====');
  console.log('1. Correct score shown:', PASS1 ? 'PASS' : 'FAIL');
  console.log('2. Reset to step 0:', PASS2 ? 'PASS' : 'FAIL');
  console.log('3. No-op drag keeps order:', PASS3 ? 'PASS' : 'FAIL');
  console.log('4. Modal close + scroll unlock:', PASS4 ? 'PASS' : 'FAIL');
  console.log('ALL:', all ? 'PASS' : 'SOME FAILED');
  child.kill();
};

