const WebSocket = require('ws');
const { spawn, execSync } = require('child_process');
const http = require('http');
const fs = require('fs');

const FILE_URL = 'file:///tmp/disc-pi-rauan7qv/run/index.html';
const PORT = 9999;
const OUT_DIR = '/tmp/ptest_out';
fs.mkdirSync(OUT_DIR, { recursive: true });
const sleep = ms => new Promise(r => setTimeout(r, ms));

function getJson() {
  return new Promise((resolve) => {
    http.get('http://localhost:' + PORT + '/json', (r) => {
      let d = '';
      r.on('data', c => d += c);
      r.on('end', () => { try { resolve(JSON.parse(d)); } catch (e) { resolve(null); } });
    }).on('error', () => resolve(null));
  });
}

// kill all chrome on this port before launching
execSync('pkill -f "remote-debugging-port=' + PORT + '" || true', { stdio: 'ignore' });
execSync('pkill -9 -f "remote-debugging-port=" || true', { stdio: 'ignore' });

let ws, msgId = 0, pending = new Map();
let child;

function cdp(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++msgId;
    pending.set(id, { resolve, reject });
    setTimeout(() => { const p = pending.get(id); if (p) { pending.delete(id); reject(new Error('timeout: ' + method)); } }, 25000);
    ws.send(JSON.stringify({ id, method, params }));
  });
}

function evaluate(expr) {
  return cdp('Page.evaluate', { expression: expr, returnByValue: true }).then(r => {
    if (r.error) throw new Error('CDP eval error: ' + JSON.stringify(r.error));
    if (r.result) return r.result.value;
    return undefined;
  });
}

