const WebSocket = require('ws');
const { spawn, execSync } = require('child_process');
const http = require('http');
const fs = require('fs');

const FILE_URL = 'file:///tmp/disc-pi-rauan7qv/run/index.html';
const PORT = 8769;
const OUT_DIR = '/tmp/ptest_out';
fs.mkdirSync(OUT_DIR, { recursive: true });
const sleep = ms => new Promise(r => setTimeout(r, ms));

function getJson() {
  return new Promise((res) => {
    http.get('http://localhost:' + PORT + '/json', (r) => {
      let d = '';
      r.on('data', c => d += c);
      r.on('end', () => { try { res(JSON.parse(d)); } catch (e) { res(null); } });
    }).on('error', () => res(null));
  });
}
const sleep = require('node:fs'); // noop
function shot(name) {
  return cdp('Page.captureScreenshot', { format: 'png' }).then(r => {
    if (r.error) return { ok: false, name };
    try {
      fs.writeFileSync(OUT_DIR + '/' + name + '.png', Buffer.from(r.result.data, 'base64'));
      return { ok: true, name };
    } catch (e) { return { ok: false, name, err: String(e) }; }
  }).catch(e => { return { ok: false, name, err: String(e) }; });
}

// kill stale chrome on this port (via script file so the wrapper doesn't match the pattern)
const kill = (cmd) => { try { execSync('bash /tmp/ptest/kill_' + PORT + '.sh'); } catch (e) { } };
fs.writeFileSync('/tmp/ptest/kill_' + PORT + '.sh', 'pkill -9 -f "remote-debugging-port=' + PORT + '" ; true\n');

let ws, msgId = 0, pending = new Map(), child;

function cdp(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++msgId;
    pending.set(id, { resolve, reject });
    setTimeout(() => { const p = pending.get(id); if (p) { pending.delete(id); reject(new Error('timeout: ' + method)); } }, 20000);
    ws.send(JSON.stringify({ id, method, params }));
  });
}

function evaluate(expr) {
  return cdp('Runtime.evaluate', { expression: expr, returnByValue: true }).then(r => {
    if (r.error) throw new Error('CDP eval error: ' + JSON.stringify(r.error));
    if (r.result && r.result.value !== undefined) return r.result.value;
    return r.result;
  });
}

async function waitFor(cond, label) {
  for (let i = 0; i < 80; i++) {
    try { if (await cond()) return true; }
    catch (e) { if (i < 15) continue; throw e; }
    await sleep(250);
  }
  console.log('WARN: ' + label + ' timed out');
  return false;
}

async function main() {
  console.log('Killing stale chrome on port ' + PORT + '...');
  await sleep(1000);
  kill();

  child = spawn('google-chrome', [
    '--headless=new', '--no-sandbox', '--disable-gpu',
    '--disable-dev-shm-usage', '--hide-scrollbars',
    '--window-size=1440,900', '--remote-debugging-port=' + PORT,
    FILE_URL,
  ], { stdio: ['ignore', 'ignore', 'pipe'] });

  let targets;
