    const lr = list.getBoundingClientRect();
    const startX = lr.left + 40;
    const startY = r.top + r.height / 2;
    const endY = lr.bottom - 2;
    const steps = 8;
    const fire = (type, x, y) => {
      first.dispatchEvent(new PointerEvent(type, {
        bubbles: true, cancelable: true, view: window,
        pointerId: 1, pointerType: 'mouse', button: 0, isPrimary: true,
        clientX: x, clientY: y,
      }));
    };
    fire('pointerdown', startX, startY);
    for (let i = 1; i <= steps; i++) {
      fire('pointermove', startX, startY + (endY - startY) * (i / steps));
    }
    fire('pointerup', startX, endY);
    return Array.from(list.children).map(li => li.dataset.type);
  }, n);

  for (let step = 0; step < 8; step++) {
    for (let li = 0; li < 3; li++) {
      const r = await dragFirstToBottom(li);
      console.log('  step' + (step + 1) + ' list' + (li + 1) + ' -> ' + JSON.stringify(r));
    }
    if (step < 7) {
      await evaluate(() => document.querySelector('[data-disc-next]').click());
    } else {
      await evaluate(() => document.querySelector('[data-disc-finish]').click());
    }
    await sleep(200);
  }

  const resState = await evaluate(() => {
