  const PASS1 = resState.score === EXPECTED;
  console.log('SCORE PASS (expected "' + EXPECTED + '"): ' + (PASS1 ? 'YES' : 'NO  got "' + resState.score + '"'));
  await shot('03_result');

  await evaluate(() => document.querySelector('#discRetry').click());
  await sleep(200);
  const resetState = await evaluate(() => {
    return {
      stepUIdisplay: document.querySelector('.disc-stepui').style.display,
      step: Array.from(document.querySelectorAll('.disc-tab')).find(x => x.classList.contains('is-active'))?.dataset.stepBtn,
      progress: document.querySelector('#discProgress').style.width,
    };
  });
  console.log('after reset: ' + JSON.stringify(resetState));
  const PASS2 = resetState.step === '0' && resetState.stepUIdisplay === '';
  console.log('RESET PASS (step 0, stepUI visible): ' + (PASS2 ? 'YES' : 'NO'));

  const noop = await evaluate(() => {
    const pane = document.querySelector('.disc-pane.is-active');
    const list = pane.querySelector('.disc-list');
    const first = list.children[0];
    const r = first.getBoundingClientRect();
    const startX = r.left + 40, startY = r.top + 20;
    const opts = { bubbles: true, clientX: startX, clientY: startY, pointerId: 1, pointerType: 'mouse', button: 0, isPrimary: true };
    first.dispatchEvent(new PointerEvent('pointerdown', { ...opts }));
    first.dispatchEvent(new PointerEvent('pointermove', { ...opts, clientX: startX + 2, clientY: startY + 2 }));
    first.dispatchEvent(new PointerEvent('pointerup', { ...opts, clientX: startX + 2, clientY: startY + 2 }));
    return Array.from(list.children).map(li => li.dataset.type);
  });
  const originalOrder = (await evaluate(() => {
    const pane = document.querySelector('.disc-pane.is-active');
    return Array.from(pane.querySelectorAll('.disc-list')).map(l => Array.from(l.children).map(li => li.dataset.type));
  }))[0];
  const PASS3 = JSON.stringify(noop) === JSON.stringify(originalOrder);
  console.log('NO-OP DRAG PASS (order unchanged): ' + (PASS3 ? 'YES' : 'NO') + ' order: ' + JSON.stringify(noop));

  await evaluate(() => {
    const m = document.querySelector('#wizardmodal');
    m.querySelector('[data-disc-close]').click();
  });
  const closeState = await evaluate(() => {
    return {
      modalOpen: document.querySelector('#wizardmodal').classList.contains('is-open'),
      bodyOverflow: document.body.style.overflow,
    };
  });
  console.log('after close: ' + JSON.stringify(closeState));
  const PASS4 = closeState.modalOpen === false && closeState.bodyOverflow === '';
  console.log('CLOSE PASS (modal closed, scroll unlocked): ' + (PASS4 ? 'YES' : 'NO'));
  await shot('04_closed');

  const all = PASS1 && PASS2 && PASS3 && PASS4;
  console.log('\n===== SUMMARY =====');
  console.log('1. Correct score shown: ' + (PASS1 ? 'PASS' : 'FAIL'));
  console.log('2. Reset to step 0: ' + (PASS2 ? 'PASS' : 'FAIL'));
  console.log('3. No-op drag keeps order: ' + (PASS3 ? 'PASS' : 'FAIL'));
  console.log('4. Modal close + scroll unlock: ' + (PASS4 ? 'PASS' : 'FAIL'));
  console.log('ALL: ' + (all ? 'PASS' : 'SOME FAILED'));
  child.kill();
}

main().catch(function (e) { console.error(e); if (child) child.kill(); process.exit(1); });

