    '<circle cx="8" cy="2.6" r="2.1" fill="currentColor"/>' +
    '<circle cx="8" cy="8"   r="2.1" fill="currentColor"/>' +
    '<circle cx="8" cy="13.4" r="2.1" fill="currentColor"/></svg>';

  function ensureHandle(item) {
    if (item.querySelector('.disc-handle')) return;
    const h = document.createElement('span');
    h.className = 'disc-handle';
    h.innerHTML = HANDLE_SVG;
    item.appendChild(h);
  }
  const items = qsa('.disc-item', modal);
  items.forEach((it) => {
    ensureHandle(it);
    it.tabIndex = 0;
    it.addEventListener('keydown', (e) => {
      if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
      e.preventDefault();
      const list = it.closest('.disc-list');
      const arr = Array.from(list.children);
      const i = arr.indexOf(it);
      const j = i + (e.key === 'ArrowDown' ? 1 : -1);
      if (j < 0 || j >= arr.length) return;
      list.insertBefore(it, arr[j]);
      it.focus({ preventScroll: true });
    });
  });

  function clearDragStyles(item, list) {
    item.classList.remove('is-dragging');
    item.style.left = '';
    item.style.top = '';
    item.style.position = '';
    item.style.zIndex = '';
    item.style.transition = '';
    list.classList.remove('is-reordering');
  }

  function onDown(e) {
    const item = e.target.closest ? e.target.closest('.disc-item') : null;
    if (!item || drag) return;
    // игнорируем многократные касания
    if (e.type === 'pointerdown' && e.pointerType === 'mouse' && e.button !== 0) return;

    const list = item.closest('.disc-list');
    const r = item.getBoundingClientRect();
    const lr0 = list.getBoundingClientRect();
    const sx = e.clientX, sy = e.clientY;
    const startLeft = r.left - lr0.left;   // позиция элемента в списке (list = position:relative)
    const startTop  = r.top  - lr0.top;
    const offX = sx - lr0.left - startLeft; // смещение указателя от левого края элемента (в координатах списка)
    const offY = sy - lr0.top  - startTop;

    drag = { item, list, sx, sy, offX, offY, started: false };

    item.classList.add('is-dragging');
    item.style.position = 'absolute';
    item.style.left = startLeft + 'px';
    item.style.top  = startTop  + 'px';
    item.style.zIndex = '20';
    list.classList.add('is-reordering');
    item.setPointerCapture(e.pointerId);
  }

  function onMove(e) {
    if (!drag) return;
    const { item, list, offX, offY, sx, sy } = drag;

    // небольшой порог — чтобы не «подхватывать» случайное касание
    if (!drag.started && Math.hypot(e.clientX - sx, e.clientY - sy) <= 5) return;
    drag.started = true;

    const lr = list.getBoundingClientRect();
    item.style.left = (e.clientX - lr.left - offX) + 'px';
    item.style.top  = (e.clientY - lr.top - offY) + 'px';


