    // find target: первый (в DOM) элемент, чей центр ниже указателя
    let target = null;
    for (const it of list.children) {
      if (it === item) continue;
      const r = it.getBoundingClientRect();
      if (e.clientY < r.top + r.height / 2) { target = it; break; }
    }

    // подсветка «прикрепления»
    qsa('.disc-item.is-over', list).forEach(el => el.classList.remove('is-over'));
    if (target) target.classList.add('is-over');

    if (target) {
      list.insertBefore(item, target);
    } else {
      if (list.lastElementChild !== item) list.appendChild(item);
    }
  }

  function onUp(e) {
    if (!drag) return;
    const { item, list } = drag;
    qsa('.disc-item.is-over', list).forEach(el => el.classList.remove('is-over'));
    clearDragStyles(item, list);
    try { item.releasePointerCapture(e.pointerId); } catch (_) {}
    drag = null;
  }

  items.forEach(item => {
    item.addEventListener('pointerdown', onDown);
    item.addEventListener('pointermove', onMove);
    item.addEventListener('pointerup', onUp);
    item.addEventListener('pointercancel', onUp);
  });

  // перетаскивание за «ручку»
  // (ручки внутри item — уже обрабатываются через closest('.disc-item'))

  /* ================= Init ================= */
  // сохранить исходный порядок для reset
  qsa('.disc-list', modal).forEach(list => {
    list._origOrder = Array.from(list.children);
  });
  renderStep();
})();
